import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";

const GENERATED_TELEPROMPTER_BANNER =
  "<!-- GENERATED FILE. DO NOT EDIT. Edit apps/anvil/teleprompter_pro.html -->";
const PNPM_BIN = process.platform === "win32" ? "pnpm.cmd" : "pnpm";
const ANVIL_DIST_WAIT_MS = 2000;
const ANVIL_DIST_POLL_MS = 100;
const RESET_DIR_MAX_RETRIES = 10;
const RESET_DIR_RETRY_DELAY_MS = 50;
const RESET_DIR_BACKOFF_ATTEMPTS = 8;
const COPY_WRITE_BACKOFF_ATTEMPTS = 6;
const RETRYABLE_RM_CODES = new Set(["ENOTEMPTY", "EBUSY", "EPERM"]);
const RETRYABLE_IO_CODES = new Set(["ENOTEMPTY", "EBUSY", "EPERM"]);

function isRetryableRmError(error) {
  if (!error || typeof error !== "object") return false;
  const code = "code" in error ? String(error.code) : "";
  return RETRYABLE_RM_CODES.has(code);
}

function isRetryableIoError(error) {
  if (!error || typeof error !== "object") return false;
  const code = "code" in error ? String(error.code) : "";
  return RETRYABLE_IO_CODES.has(code);
}

async function copyFileRobust(src, dest) {
  for (let attempt = 0; attempt < COPY_WRITE_BACKOFF_ATTEMPTS; attempt += 1) {
    try {
      fs.copyFileSync(src, dest);
      return;
    } catch (error) {
      if (!isRetryableIoError(error)) throw error;
      if (attempt === COPY_WRITE_BACKOFF_ATTEMPTS - 1) {
        throw new Error(`[sync-anvil] failed to copy file after retries: ${dest}`);
      }
      await sleep(RESET_DIR_RETRY_DELAY_MS * (attempt + 1));
    }
  }
}

async function writeFileRobust(filePath, contents) {
  for (let attempt = 0; attempt < COPY_WRITE_BACKOFF_ATTEMPTS; attempt += 1) {
    try {
      fs.writeFileSync(filePath, contents, "utf8");
      return;
    } catch (error) {
      if (!isRetryableIoError(error)) throw error;
      if (attempt === COPY_WRITE_BACKOFF_ATTEMPTS - 1) {
        throw new Error(`[sync-anvil] failed to write file after retries: ${filePath}`);
      }
      await sleep(RESET_DIR_RETRY_DELAY_MS * (attempt + 1));
    }
  }
}

async function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      await copyDir(s, d);
    } else {
      await copyFileRobust(s, d);
    }
  }
}

async function rmDirRobust(dir) {
  for (let attempt = 0; attempt < RESET_DIR_BACKOFF_ATTEMPTS; attempt += 1) {
    try {
      fs.rmSync(dir, {
        recursive: true,
        force: true,
        maxRetries: RESET_DIR_MAX_RETRIES,
        retryDelay: RESET_DIR_RETRY_DELAY_MS,
      });
      if (!fs.existsSync(dir)) {
        return;
      }
    } catch (error) {
      if (!isRetryableRmError(error)) throw error;
    }
    if (attempt === RESET_DIR_BACKOFF_ATTEMPTS - 1) {
      throw new Error(`[sync-anvil] failed to fully remove mirror dir after retries: ${dir}`);
    }
    await sleep(RESET_DIR_RETRY_DELAY_MS * (attempt + 1));
  }
}

async function resetDir(dir) {
  if (fs.existsSync(dir)) {
    await rmDirRobust(dir);
  }
  fs.mkdirSync(dir, { recursive: true });
}

function stripGeneratedBanner(html) {
  return html.replace(
    /^<!-- GENERATED FILE\. DO NOT EDIT\. Edit apps\/anvil\/teleprompter_pro\.html -->\r?\n?/,
    "",
  );
}

function stripHostShimStylesheet(html) {
  return html
    .replace(/[ \t]*<link\s+rel=["']stylesheet["']\s+href=["']\/anvil\/host-shim\.css["']\s*>\r?\n?/gi, "")
    .replace(/[ \t]*<link\s+href=["']\/anvil\/host-shim\.css["']\s+rel=["']stylesheet["']\s*>\r?\n?/gi, "");
}

async function tagGeneratedTeleprompter(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`[sync-anvil] missing expected file for tagging: ${filePath}`);
    return false;
  }
  const html = fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, "");
  const normalized = stripGeneratedBanner(html);
  const cleaned = stripHostShimStylesheet(normalized);
  const newline = cleaned.includes("\r\n") ? "\r\n" : "\n";
  const tagged = `${GENERATED_TELEPROMPTER_BANNER}${newline}${cleaned}`;
  return writeFileRobust(filePath, tagged);
}

function writeGeneratedReadme(destDir) {
  const readmePath = path.join(destDir, "GENERATED.md");
  const body = `# Generated Mirror

This folder is generated by \`pnpm --filter nursery sync:anvil\`.

- Source of truth HTML: \`apps/anvil/teleprompter_pro.html\`
- Build output source: \`apps/anvil/dist/**\`
- Mirror target: \`apps/nursery/public/anvil/**\`

Do not edit files here manually; they are overwritten by sync.
`;
  fs.writeFileSync(readmePath, body, "utf8");
}

function hashFile(filePath) {
  return fs.readFileSync(filePath);
}

function listRelativeFiles(rootDir) {
  const files = [];
  const stack = [rootDir];
  while (stack.length > 0) {
    const currentDir = stack.pop();
    if (!currentDir) continue;
    for (const entry of fs.readdirSync(currentDir, { withFileTypes: true })) {
      const fullPath = path.join(currentDir, entry.name);
      if (entry.isDirectory()) {
        stack.push(fullPath);
        continue;
      }
      files.push(path.relative(rootDir, fullPath));
    }
  }
  files.sort();
  return files;
}

function verifyMirroredTree(srcDir, destDir) {
  const mirrorManagedDestFiles = listRelativeFiles(destDir).filter(
    (relativePath) => relativePath !== "GENERATED.md",
  );
  const srcFiles = listRelativeFiles(srcDir);
  const missingFiles = [];
  const mismatchedFiles = [];
  for (const relativePath of srcFiles) {
    const srcFile = path.join(srcDir, relativePath);
    const destFile = path.join(destDir, relativePath);
    if (!fs.existsSync(destFile)) {
      missingFiles.push(relativePath);
      continue;
    }
    if (relativePath === "teleprompter_pro.html") {
      continue;
    }
    if (!hashFile(srcFile).equals(hashFile(destFile))) {
      mismatchedFiles.push(relativePath);
    }
  }
  const extraFiles = mirrorManagedDestFiles.filter((relativePath) => !srcFiles.includes(relativePath));
  if (missingFiles.length > 0 || mismatchedFiles.length > 0 || extraFiles.length > 0) {
    const details = [
      missingFiles.length > 0 ? `missing=${missingFiles.join(",")}` : "",
      mismatchedFiles.length > 0 ? `mismatched=${mismatchedFiles.join(",")}` : "",
      extraFiles.length > 0 ? `extra=${extraFiles.join(",")}` : "",
    ]
      .filter(Boolean)
      .join(" ");
    throw new Error(`[sync-anvil] mirror verification failed: ${details}`);
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function ensureAnvilDist(src, workspaceRoot) {
  if (fs.existsSync(src)) {
    return;
  }

  // In recursive builds, Anvil may still be producing dist; wait briefly first.
  const deadline = Date.now() + ANVIL_DIST_WAIT_MS;
  while (Date.now() < deadline) {
    await sleep(ANVIL_DIST_POLL_MS);
    if (fs.existsSync(src)) {
      return;
    }
  }

  console.warn(`[sync-anvil] missing: ${src}`);
  console.warn("[sync-anvil] running teleprompter build to generate dist.");

  const buildResult = spawnSync(PNPM_BIN, ["--filter", "teleprompter", "build"], {
    cwd: workspaceRoot,
    stdio: "inherit",
  });

  if (buildResult.status !== 0) {
    process.exit(buildResult.status ?? 1);
  }

  if (!fs.existsSync(src)) {
    console.error(`[sync-anvil] missing after build: ${src}`);
    process.exit(1);
  }
}

const nurseryRoot = process.cwd();
const src = path.resolve(nurseryRoot, "..", "anvil", "dist");
const dest = path.resolve(nurseryRoot, "public", "anvil");
const workspaceRoot = path.resolve(nurseryRoot, "..", "..");

await ensureAnvilDist(src, workspaceRoot);

await resetDir(dest);
await copyDir(src, dest);

const mirroredTeleprompter = path.join(dest, "teleprompter_pro.html");
await tagGeneratedTeleprompter(mirroredTeleprompter);
const legacyHostShimPath = path.join(dest, "host-shim.css");
if (fs.existsSync(legacyHostShimPath)) {
  try {
    fs.rmSync(legacyHostShimPath, { force: true });
  } catch (error) {
    if (!isRetryableRmError(error)) throw error;
    console.warn(`[sync-anvil] could not remove locked legacy host shim: ${legacyHostShimPath}`);
  }
}
writeGeneratedReadme(dest);
verifyMirroredTree(src, dest);

console.log(`[sync-anvil] ${src} -> ${dest} (one-way mirror)`);
